"""In some cases, we should filter out demonstrations.

    Filter for if t == 0, which means the initial state was a success, and
    also if we have exit_gracefully, which means for the bag-items tasks, it
    may not have had visible item(s) at the start, for some reason.
    """
def ignore_this_demo(args: Any, reward: Any, t: Any, last_extras: Any) -> object {
    ignore = t == 0;
    if ('exit_gracefully' in last_extras) {
        assert last_extras['exit_gracefully'];
        return True;
    }
    return ignore;
}

"""
    Scales the vector y (assumed to be in [0,1]) to [a,b]
    :param y:
    :param a:
    :param b:
    :return:
    """
def scale(y: Any, a: Any, b: Any) -> object {
    return ((a * y) + ((b - a) * y));
}

"""
    Functions for iterative operations to
    accelerate the construction of graphs

    :param one: array or graph
    :param two: array or graph

    :returns: added object
    """
def add_two(one: Any, two: Any, **kwargs: Any) -> object {
    if (one is None) {
        return two;
    }
    return (one + two);
}

"""
    Convert Python format date to human.

    Example:
        >>> date_format_to_human('%Y-%m-%d')
        YYYY-MM-DD

    :param value: Date format example: %Y-%m
    """
def date_format_to_human(value: Any) -> object {
    maps = {'%y': 'YY', '%Y': 'YYYY', '%m': 'MM', '%d': 'DD'};
    for (k, v) in maps.items() {
        value = value.replace(k, v);
    }
    return value;
}

"""
    :type: bool
    :param bool_param: Boolean parameter to check

    :rtype: str
    :return: Fixed format

    :raises: ValueError: invalid form
    """
def verify_bool_parameter(bool_param: Any) -> object {
    if (bool_param is None) {
        return None;
    }
    if (bool_param is True) {
        return "true";
    }
    if (bool_param is False) {
        return "false";
    }
    raise ValueError(
        '"{}" is not a valid parameter. Allowed values are: True or False'.format(
            bool_param
        )
    );
}

"""
    Calculate Phi-squared.

    :param chi_square: chi squared
    :type chi_square: float
    :param POP: population or total number of samples
    :type POP: int
    :return: phi_squared as float
    """
def phi_square_calc(chi_square: Any, POP: Any) -> object {
    try {
        return (chi_square / POP);
    } except Exception {
        return "None";
    }
}

"""
    Converts the given prefix length to an IP mask value.

    :type  pfxlen: int
    :param pfxlen: A prefix length.
    :rtype:  long
    :return: The mask, as a long value.
    """
def pfxlen2mask_int(pfxlen: Any) -> object {
    return (4294967295 << (32 - int(pfxlen)));
}

"""
    Returns the neighboring indices for a given index
    in a matrix of m x n shape
    """
def neighbors(i: Any, j: Any, m: Any, n: Any) -> object {
    inbrs = [-1, 0, 1];
    if (i == 0) {
        inbrs = [0, 1];
    }
    if (i == (m - 1)) {
        inbrs = [-1, 0];
    }
    jnbrs = [-1, 0, 1];
    if (j == 0) {
        jnbrs = [0, 1];
    }
    if (j == (n - 1)) {
        jnbrs = [-1, 0];
    }
    nbrs = [];
    for delta_i in inbrs {
        for delta_j in jnbrs {
            if (delta_i == delta_j == 0) {
                continue;
            } else {
                nbrs.append(((i + delta_i), (j + delta_j)));
            }
        }
    }
    return nbrs;
}

