"""
    Check that contain of iterable ``to_check`` is among iterable ``original``.
    :param to_check:
        Iterable with elements to check.
    :param original:
        Iterable with elements to check to.
    :return:
        Boolean.
    """
def check_issubset(to_check: Any, original: Any) -> object {
    s = `set();
    for item in to_check {
        s.add(item);
    }
    return s.issubset(original);
}

"""Adjust linebreaks to match ';', strip leading/trailing whitespace.

    list_of_commandlines=_adjust_lines(input_text)
    Lines are adjusted so that no linebreaks occur within a commandline
    (except matrix command line)
    """
def _adjust_lines(lines: Any) -> object {
    formatted_lines = [];
    for l in lines {
        l = l.replace('\r\n', '\n').replace('\r', '\n').strip();
        if l.lower().startswith('matrix') {
            formatted_lines.append(l);
        } else {
            l = l.replace('\n', ' ');
            if l {
                formatted_lines.append(l);
            }
        }
    }
    return formatted_lines;
}
